style.css:
/* ==========================================
   CK_777'S PASTEL PINK ROBLOX THEME
   ========================================== */
@-moz-document domain("roblox.com") {
:root {
    --pink-bg: #FFF7FB;
    --pink-light: #FFEAF2;
    --pink-soft: #FFD2E3;
    --pink-medium: #FFC1D9;
    --pink-strong: #F59CBD;
    --pink-dark: #DF78A5;
    --pink-text: #A85D7C;
    --white: #FFFFFF;
}

/* MAIN PAGE BACKGROUND */
html,
body,
#container-main,
.content,
.home-container,
.section-content {
    background-color: var(--pink-bg) !important;
}

/* TOP NAVIGATION */
#header,
.navbar,
.navbar-fixed-top,
#navigation {
    background: var(--pink-light) !important;
    border-bottom: 1px solid var(--pink-soft) !important;
}

/* LEFT SIDEBAR */
#navigation,
.left-navigation,
.navigation,
.menu-vertical {
    background-color: var(--white) !important;
}

/* SIDEBAR HOVER */
#navigation a:hover,
.left-navigation a:hover,
.menu-vertical a:hover {
    background-color: var(--pink-light) !important;
    border-radius: 12px !important;
}

/* SEARCH BAR */
input,
input[type="text"],
input[type="search"],
.search-input,
#navbar-search-input {
    border-color: var(--pink-soft) !important;
    border-radius: 20px !important;
}

input:focus,
.search-input:focus {
    border-color: var(--pink-strong) !important;
    box-shadow: 0 0 0 2px var(--pink-light) !important;
}

/* GENERAL BUTTONS */
button,
.btn-control,
.btn-secondary-md,
.btn-secondary-lg {
    border-radius: 12px !important;
}

/* DOWNLOAD BUTTON */
#navbar-download,
.navbar-download,
a.btn-growth-md,
button.btn-growth-md,
.btn-growth-md,
a[href*="download"],
button[aria-label*="Download"] {
    background: var(--pink-strong) !important;
    background-color: var(--pink-strong) !important;
    border-color: var(--pink-strong) !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
}

#navbar-download:hover,
.navbar-download:hover,
a.btn-growth-md:hover,
.btn-growth-md:hover,
a[href*="download"]:hover {
    background: var(--pink-dark) !important;
    border-color: var(--pink-dark) !important;
}

/* GAME CARDS */
.game-card,
.game-card-container,
.list-item,
.game-card-link {
    border-radius: 14px !important;
}

/* GAME CARD HOVER */
.game-card:hover,
.game-card-container:hover {
    box-shadow: 0 4px 14px rgba(245, 156, 189, 0.25) !important;
}

/* GAME PLAY BUTTON */
.btn-common-play-game-lg,
.btn-common-play-game-md,
.game-play-button {
    background: var(--pink-strong) !important;
    border-color: var(--pink-strong) !important;
    color: #FFFFFF !important;
    border-radius: 12px !important;
}

.btn-common-play-game-lg:hover,
.btn-common-play-game-md:hover,
.game-play-button:hover {
    background: var(--pink-dark) !important;
}

/* DROPDOWNS AND POPUPS */
.dropdown-menu,
.popover,
.tooltip,
.modal-content,
.modal-dialog {
    background-color: var(--white) !important;
    border: 1px solid var(--pink-soft) !important;
    border-radius: 14px !important;
}

/* DROPDOWN HOVER */
.dropdown-menu li:hover,
.dropdown-menu a:hover {
    background-color: var(--pink-light) !important;
}

/* FRIENDS AND CHAT PANELS */
.chat-container,
#chat,
.friend-tile,
.friends-list {
    border-radius: 14px !important;
}

/* TOP-RIGHT FRIENDS AND CHAT ICONS */
#btr-navbar-friends,
#btr-navbar-messages {
    position: relative !important;
    top: -25px !important;
}

/* AVATAR EDITOR TABS */
#horizontal-tabs .rbx-tab,
#horizontal-tabs .rbx-tab.seven-tab {
    background-color: var(--pink-light) !important;
    border-radius: 12px !important;
}

#horizontal-tabs .rbx-tab-heading {
    background-color: var(--pink-light) !important;
    color: var(--pink-text) !important;
    border-radius: 12px !important;
}

/* AVATAR TAB HOVER */
#horizontal-tabs .rbx-tab:hover,
#horizontal-tabs .rbx-tab-heading:hover {
    background-color: var(--pink-soft) !important;
}

/* SELECTED AVATAR TAB */
#horizontal-tabs .rbx-tab.active,
#horizontal-tabs .rbx-tab.active .rbx-tab-heading {
    background-color: var(--pink-soft) !important;
    color: var(--pink-text) !important;
}

/* FRIENDS PAGE - PINK FRIEND CARDS */
.hlist.avatar-cards .avatar-card-container {
    background: var(--pink-light) !important;
    border: 1px solid var(--pink-soft) !important;
    border-radius: 12px !important;
}

/* FRIEND CARD HOVER */
.hlist.avatar-cards .avatar-card-container:hover {
    background: #FFDCE9 !important;
}

/* EXTRA FRIEND CARD SELECTORS */
.friends-list .list-item,
.friends-list .friend-tile,
.friends-list .list-item-container,
#friends-list .list-item,
#friends-list .friend-tile,
.friend-tile,
.friends-list .list-item-content {
    background-color: var(--pink-light) !important;
    border-color: var(--pink-soft) !important;
    border-radius: 12px !important;
}

.friends-list .list-item:hover,
.friends-list .friend-tile:hover,
#friends-list .list-item:hover,
#friends-list .friend-tile:hover,
.friend-tile:hover {
    background-color: #FFDCE9 !important;
}

/* LINKS */
a:hover {
    color: var(--pink-dark) !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 9px !important;
}

::-webkit-scrollbar-track {
    background: var(--pink-bg) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--pink-medium) !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--pink-dark) !important;
}

/* TEXT SELECTION */
::selection {
    background: var(--pink-medium) !important;
    color: #FFFFFF !important;
}

/* CHECKBOXES */
input[type="checkbox"] {
    accent-color: var(--pink-strong) !important;
}

/* REMOVE ROPRO VERIFY USER BOX */
li.rbx-upgrade-now {
    display: none !important;
}
}
